package org.apache.commons.math3.analysis.differentiation;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.apache.commons.math3.exception.DimensionMismatchException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.util.ArithmeticUtils;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathArrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class DSCompiler_atan2_TriageGen0Test {

    private static final double EPSILON = 1e-14;





    @Test
    public void testAtan2_SpecialCases() {
        int parameters = 1;
        int order = 1;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        // Case: x = 0, y = 0
        x[0] = 0.0;
        y[0] = 0.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(0.0, 0.0), result[0], EPSILON);

        // Case: x = 0, y = 1
        x[0] = 0.0;
        y[0] = 1.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(1.0, 0.0), result[0], EPSILON);

        // Case: x = -1, y = 0
        x[0] = -1.0;
        y[0] = 0.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(0.0, -1.0), result[0], EPSILON);

        // Case: Infinity
        x[0] = Double.POSITIVE_INFINITY;
        y[0] = 1.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(1.0, Double.POSITIVE_INFINITY), result[0], EPSILON);

        // Case: Negative Infinity
        x[0] = Double.NEGATIVE_INFINITY;
        y[0] = 1.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(1.0, Double.NEGATIVE_INFINITY), result[0], EPSILON);
    }




}

